private void ModifyPivotQuestionColumns()
{
    if (dtbQuestion == null || dtbData == null)
        return;

    int intQuestionNo = 1;
    foreach (DataRow drwQuestion in dtbQuestion.Rows)
    {
        if (Convert.IsDBNull(drwQuestion["OrderIndex"]))
            continue;

        int intOrderIndex = Convert.ToInt32(drwQuestion["OrderIndex"]);
        string strField = String.Format("Cau{0}", intOrderIndex);
        string strCaption = drwQuestion["QuestionContent"].ToString();

        if (!dtbData.Columns.Contains(strField))
            continue;

        GridColumn gcolValue = gvData.Columns[strField];
        if (gcolValue == null)
        {
            gcolValue = gvData.Columns.ColumnByFieldName(strField);
        }
        if (gcolValue == null)
        {
            gcolValue = gvData.Columns.AddField(strField);
            gvData.Columns.Add(gcolValue);
        }

        gcolValue.FieldName = strField;
        gcolValue.Caption = String.Format("Câu {0}", intQuestionNo);
