        gcolValue.Visible = true;
        gcolValue.Width = 70;
        gcolValue.AppearanceHeader.Options.UseTextOptions = true;
        gcolValue.AppearanceHeader.TextOptions.WordWrap = WordWrap.Wrap;
        gcolValue.AppearanceHeader.TextOptions.HAlignment = HorzAlignment.Center;
        gcolValue.DisplayFormat.FormatType = FormatType.Numeric;
        gcolValue.DisplayFormat.FormatString = "n2";

        intQuestionNo++;
    }

    foreach (GridColumn gcol in gvData.Columns)
    {
        if (gcol.FieldName == null || !gcol.FieldName.StartsWith("Cau"))
            continue;

        string strIndex = gcol.FieldName.Replace("Cau", "");
        int intIndex = 0;
        if (!int.TryParse(strIndex, out intIndex))
            continue;

        DataRow[] rowsQuestion = dtbQuestion.Select("OrderIndex=" + intIndex.ToString());
        if (rowsQuestion.Length == 0)
            gcol.Visible = false;
    }
}

